SELECT PetType, MAX(weight) AS max_weight
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(pet_age) AS average_lifespan, MAX(pet_age) AS maximum_lifespan
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(pet_age) AS avg_lifespan, MAX(pet_age) AS max_lifespan
FROM Pets
GROUP BY PetType;

SELECT DISTINCT Student.Fname, Student.Age
FROM Student
JOIN Has_Pet ON Student.StuID = Has_Pet.StuID;

SELECT StuID, COUNT(PetID) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT StuID, COUNT(PetID) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT DISTINCT s.Fname, s.Sex
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT car_makers.FullName, car_makers.Id, model_list.Model
FROM car_makers
JOIN model_list ON car_makers.Id = model_list.Maker;

SELECT a.Airline
FROM airlines a
WHERE EXISTS (
    SELECT 1 FROM flights f
    WHERE f.Airline = a.uid AND f.SourceAirport = 'CVO'
)
AND NOT EXISTS (
    SELECT 1 FROM flights f
    WHERE f.Airline = a.uid AND f.SourceAirport = 'APG'
);

SELECT a.Airline
FROM airlines a
WHERE EXISTS (
    SELECT 1 FROM flights f
    WHERE f.Airline = a.uid AND f.SourceAirport = 'CVO'
)
AND NOT EXISTS (
    SELECT 1 FROM flights f
    WHERE f.Airline = a.uid AND f.SourceAirport = 'APG'
);

SELECT country_code, COUNT(*) AS player_count
FROM players
GROUP BY country_code;

SELECT country_code, COUNT(*) AS player_count
FROM players
GROUP BY country_code;

SELECT ranking_date, SUM(tours) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT hand, COUNT(*) AS player_count
FROM players
GROUP BY hand;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT DISTINCT c.course_name
FROM Courses c
JOIN Student_Enrolment_Courses sec ON c.course_id = sec.course_id;

SELECT s.first_name, s.last_name, a.line_1, a.line_2, a.line_3, a.city, a.zip_postcode, a.state_province_county, a.country
FROM Students s
JOIN Addresses a ON s.current_address_id = a.address_id;

SELECT Directed_by, COUNT(*) AS anime_count
FROM Cartoon
GROUP BY Directed_by;

SELECT Nationality, COUNT(*) AS 人口
FROM people
GROUP BY Nationality;

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT DISTINCT c.Name
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT DISTINCT c.Name
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT grade, COUNT(*) AS count
FROM Highschooler
GROUP BY grade;

SELECT grade, COUNT(*) AS student_count
FROM Highschooler
GROUP BY grade;

SELECT student_id, COUNT(friend_id) AS friend_count
FROM Friend
GROUP BY student_id;

SELECT student_id, COUNT(*) AS like_count
FROM Likes
GROUP BY student_id;

SELECT student_id, COUNT(*) AS like_count
FROM Likes
GROUP BY student_id;

SELECT t.date_of_treatment, p.first_name, p.last_name
FROM Treatments t
JOIN Professionals p ON t.professional_id = p.professional_id;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT Owners.first_name, Dogs.name
FROM Owners
JOIN Dogs ON Owners.owner_id = Dogs.owner_id;

SELECT d.date_arrived, d.date_departed
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT DISTINCT d.date_arrived, d.date_departed
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT role_code, first_name, last_name, city, state
FROM Professionals
WHERE city LIKE '%West%';
